INSERT INTO feature VALUES('certified-conversion','conversion','Conversion certified by trace replay',NULL,'implemented','notable',NULL,'The untrusted engine''s conversion trace is replayed step by step by the kernel, which certifies, refutes or declines it. The replay reduces under an environment and walks each weak head once. A read of a variable bound to a variable takes one hop.','kernel-conversion-trace kernel-core core-nbe','crates/kernel-conversion-trace/tests/differential.rs',NULL,NULL);
